param([Parameter(Mandatory=$true)][ValidateRange(1,2147483647)][int]$RootProcessId)
$ErrorActionPreference='Stop';$entries=@(Get-CimInstance Win32_Process -Property ProcessId,ParentProcessId,Name -OperationTimeoutSec 8);$owned=[Collections.Generic.HashSet[int]]::new();[void]$owned.Add($RootProcessId);do{$changed=$false;foreach($entry in $entries){if($owned.Contains([int]$entry.ParentProcessId)-and $owned.Add([int]$entry.ProcessId)){$changed=$true}}}while($changed);$where=(@($owned)|ForEach-Object {'ProcessId='+$_})-join ' OR ';$details=@(Get-CimInstance Win32_Process -Filter $where -Property ProcessId,ParentProcessId,CommandLine -OperationTimeoutSec 8);$rows=@(foreach($entry in $details){if($entry.CommandLine -match '(?:^|\s)--type=renderer(?:\s|$)'){try{$process=Get-Process -Id $entry.ProcessId -ErrorAction Stop;[pscustomobject]@{processId=[int]$entry.ProcessId;parentProcessId=[int]$entry.ParentProcessId;role='renderer';privateBytes=$process.PrivateMemorySize64;handles=$process.HandleCount}}catch{}}});if($rows.Count -eq 0){throw 'No renderer found under exact owned fixture root'};$types=(& (Join-Path $PSScriptRoot '../inspect-process-handle-types.ps1') -OwnedPids @($rows.processId))|ConvertFrom-Json;foreach($row in $rows){$match=$types.processes|Where-Object {$_.ProcessId -eq $row.processId}|Select-Object -First 1;$row|Add-Member -NotePropertyName sections -NotePropertyValue $match.Types.Section};[pscustomobject]@{atUtc=[DateTime]::UtcNow.ToString('o');ownedProcessCount=$owned.Count;renderers=$rows}|ConvertTo-Json -Depth 4 -Compress
